const errorText=(error:unknown)=>error instanceof Error?error.message:'No se pudo guardar. Tus datos siguen en el formulario.';
const localTime=(value:string|null|undefined)=>value?new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)).replace(' ','T'):'';
const instant=(value:string)=>value?new Date(value+':00-05:00').toISOString():iso();
const personName=(state:AppState, clientId:string|null, fallback:string)=>state.clients.find(c=>c.id===clientId)?.name||fallback||'Contacto por identificar';
const contactPhone=(state:AppState, inquiry:Inquiry)=>state.clients.find(c=>c.id===inquiry.clientId)?.phone||inquiry.contact;
const tone=(status:string):'neutral'|'success'|'warning'|'danger'|'purple'=>status==='Cancelado'||status==='No se concretó'?'danger':status==='Entregado'||status==='Completada'?'success':status==='Por responder'||status==='Por confirmar'?'warning':status==='Confirmado'||status==='Con pedido'?'purple':'neutral';

/** Short-lived per-user drafts; never a substitute for the shared business state. */
export function useFormDraft<T extends Base>(kind:string, initial:T) {
  const {state,actor,mode}=useCRM();
  const key=`mr:form:${state.businessId}:${actor}:${mode}:${kind}`;
  const [draft,setDraft]=useState<T>(()=>{try{const stored=sessionStorage.getItem(key);if(stored){const parsed=JSON.parse(stored) as T;if(parsed.id&&parsed.revision!=null)return parsed;}}catch{/* storage unavailable */}return initial;});
  const [dirty,setDirty]=useState(false);
  useEffect(()=>{try{sessionStorage.setItem(key,JSON.stringify(draft));}catch{/* retain the in-memory form */}},[draft,key]);
  useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[dirty]);
  const change=(value:T|((previous:T)=>T))=>{setDraft(value);setDirty(true);};
  const clear=()=>{sessionStorage.removeItem(key);setDirty(false);};
  const reset=()=>{setDraft(initial);setDirty(false);sessionStorage.removeItem(key);};
  return {draft,setDraft:change,clear,reset,dirty};
}

export function blankOrder(profile:Person, inquiry?:Inquiry):Order {
  const b=base();
  return {...b,code:`MR-${today().replaceAll('-','')}-${b.id.slice(0,5).toUpperCase()}`,clientId:inquiry?.clientId||null,contactName:inquiry?.contactName||'',inquiryId:inquiry?.id||null,modality:inquiry?.modality==='Catering'?'Catering':'Productos',need:inquiry?.need||'Por conocer',status:'Borrador',responsible:profile,deliveryDate:inquiry?.requestedDate||'',deliveryTime:'',location:'',deliveryMode:'Entrega',lines:[],scope:[],attendees:null,duration:'',eventId:null,parentId:null,transport:null,extra:0,discount:0,total:0,paymentTerms:'',changesTerms:'',customerNotes:'',internalNotes:'',acceptedAt:null,acceptedChannel:'',capacityCheckedAt:null,capacityCheckedBy:null,confirmedAt:null,deliveredAt:null,dueDate:'',cancelReason:'',cancelCharge:0,versions:[],costEstimate:null,costReviewed:false,costRevision:0,isSimulation:false};
}

export function lineFromReference(state:AppState, reference:string):OrderLine {
  const [kind,referenceId]=reference.split(':');
  const p=state.products.find(x=>x.id===referenceId),option=state.options.find(x=>x.id===referenceId);
  if(kind==='product'&&p)return {id:id(),referenceId:p.id,referenceType:'product',name:p.name,quantity:p.baseQuantity,unit:p.unit,unitsPerPack:1,baseQuantity:p.baseQuantity,unitPrice:p.price,priceKind:p.priceKind,attributes:Object.entries(p.attributes).filter(([,v])=>v).map(([k,v])=>`${({filling:'Relleno',cacao:'Cacao',shape:'Forma',size:'Tamaño',coverage:'Cobertura',decoration:'Decoración',presentation:'Presentación'} as Record<string,string>)[k]}: ${v}`).join(' · '),distribution:[],sourceVersion:p.revision,costVersionId:state.costs.filter(c=>c.referenceId===p.id&&c.reviewed).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0]?.id||null,notes:''};
  if(kind==='option'&&option)return {id:id(),referenceId:option.id,referenceType:'option',name:option.name,quantity:1,unit:'paquete',unitsPerPack:option.items.reduce((n,x)=>n+x.quantity,0)||1,baseQuantity:1,unitPrice:option.price,priceKind:option.priceKind,attributes:[option.presentation,option.items.map(x=>`${x.quantity} ${state.products.find(p=>p.id===x.productId)?.name||'Producto'}`).join(' + '),option.included].filter(Boolean).join(' · '),distribution:[],sourceVersion:option.revision,costVersionId:state.costs.filter(c=>c.referenceId===option.id&&c.reviewed).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0]?.id||null,notes:''};
  return {id:id(),referenceId:null,referenceType:'custom',name:'',quantity:1,unit:'unidad',unitsPerPack:1,baseQuantity:1,unitPrice:null,priceKind:'Consultar',attributes:'',distribution:[],sourceVersion:null,costVersionId:null,notes:''};
}

export function OrderLinesEditor({lines,onChange,state}:{lines:OrderLine[];onChange:(lines:OrderLine[])=>void;state:AppState}) {
  const [reference,setReference]=useState('');
  const update=(lineId:string,patch:Partial<OrderLine>)=>onChange(lines.map(l=>l.id===lineId?{...l,...patch}:l));
  const setPrice=(lineId:string,text:string)=>{try{update(lineId,{unitPrice:text.trim()?cents(text):null,priceKind:text.trim()?'Aprobado':'Consultar'});}catch{/* leave the last valid value; the money input below accepts decimals */}};
  return <div className="stack"><div className="toolbar"><Field label="Añadir desde Productos y precios"><Select value={reference} onChange={e=>setReference(e.target.value)}><option value="">Selecciona una referencia</option><optgroup label="Productos revisados">{state.products.filter(p=>p.status==='Aprobado'&&!p.archived).map(p=><option key={p.id} value={'product:'+p.id}>{p.name} · {money(p.price)} / {p.baseQuantity} {p.unit}</option>)}</optgroup><optgroup label="Opciones de compra revisadas">{state.options.filter(p=>p.status==='Aprobado'&&!p.archived).map(p=><option key={p.id} value={'option:'+p.id}>{p.name} · {money(p.price)}</option>)}</optgroup></Select></Field><Button type="button" variant="secondary" disabled={!reference} onClick={()=>{onChange([...lines,lineFromReference(state,reference)]);setReference('');}}>Añadir</Button><Button type="button" variant="ghost" onClick={()=>onChange([...lines,lineFromReference(state,'custom:')])}>Añadir una línea específica</Button><Link className="text-link" to="/productos">Productos y precios</Link></div>
  {!lines.length&&<Empty title="¿Qué recibirá el cliente?" text="Elige una referencia revisada o describe una cotización específica. Puedes guardar mientras precisas el contenido."/>}
  {lines.map((line,index)=><Card key={line.id} title={`Contenido ${index+1}`} action={<Button type="button" variant="ghost" onClick={()=>onChange(lines.filter(l=>l.id!==line.id))}>Quitar</Button>}><div className="form-grid">
    <Field label="Producto u opción" hint="Este nombre y estos atributos se conservarán en el pedido."><Input value={line.name} onChange={e=>update(line.id,{name:e.target.value})}/></Field>
    <Field label="Cantidad de unidades de venta"><Input type="number" min="1" step="1" value={line.quantity||''} onChange={e=>update(line.id,{quantity:Number(e.target.value)})}/></Field>
    <Field label="Unidad de venta" hint="Caja, paquete, unidad, botella o lote."><Input value={line.unit} onChange={e=>update(line.id,{unit:e.target.value})}/></Field>
    <Field label="Productos dentro de cada unidad de venta" hint="Por ejemplo, 12 chocotejas dentro de cada caja; 1 cuando se vende por unidad."><Input type="number" min="1" step="1" value={line.unitsPerPack||''} onChange={e=>update(line.id,{unitsPerPack:Number(e.target.value)})}/></Field>
    <MoneyInput label="Precio cotizado (S/)" hint={`Importe por ${line.baseQuantity} ${line.unit}. Revisa los cambios con el cliente.`} value={line.unitPrice} onChange={text=>setPrice(line.id,text)}/>
    <Field label="Ese precio corresponde a cuántas unidades" hint="Una tarifa por 100 no autoriza vender menos con precio proporcional."><Input type="number" min="1" step="1" value={line.baseQuantity||''} onChange={e=>update(line.id,{baseQuantity:Number(e.target.value)})}/></Field>
    <div className="span-2"><Field label="Relleno, cobertura, forma, tamaño y presentación"><Textarea value={line.attributes} onChange={e=>update(line.id,{attributes:e.target.value})}/></Field></div>
    <div className="span-2"><Field label="Cambios o notas de esta línea"><Input value={line.notes} onChange={e=>update(line.id,{notes:e.target.value})}/></Field></div>
  </div><details><summary>Distribuir rellenos o variantes ({line.quantity*line.unitsPerPack} productos en total)</summary><div className="stack">{line.distribution.map((d,j)=><div className="row" key={j}><Field label="Variante"><Input value={d.variant} onChange={e=>update(line.id,{distribution:line.distribution.map((v,k)=>k===j?{...v,variant:e.target.value}:v)})}/></Field><Field label="Cantidad"><Input type="number" min="1" step="1" value={d.quantity||''} onChange={e=>update(line.id,{distribution:line.distribution.map((v,k)=>k===j?{...v,quantity:Number(e.target.value)}:v)})}/></Field><Button type="button" variant="ghost" onClick={()=>update(line.id,{distribution:line.distribution.filter((_,k)=>k!==j)})}>Quitar</Button></div>)}<Button type="button" variant="secondary" onClick={()=>update(line.id,{distribution:[...line.distribution,{variant:'',quantity:0}]})}>Añadir variante</Button>{line.distribution.length>0&&<Notice tone={line.distribution.reduce((n,d)=>n+d.quantity,0)===line.quantity*line.unitsPerPack?'success':'warning'}>Distribución: {line.distribution.reduce((n,d)=>n+d.quantity,0)} de {line.quantity*line.unitsPerPack}. Debe coincidir antes de confirmar.</Notice>}</div></details></Card>)}
  </div>;
}

/** Keep partially typed monetary text usable; commit only unambiguous cents. */
export function MoneyInput({label,hint,value,onChange,disabled=false}:{label:string;hint?:string;value:number|null;onChange:(text:string)=>void;disabled?:boolean}) {
  const [text,setText]=useState(decimal(value)),[error,setError]=useState('');
  useEffect(()=>{if(text.trim()){try{if(cents(text)===value)return;}catch{/* keep partial text */}}setText(decimal(value));},[value]);
  return <Field label={label} hint={hint} error={error}><Input inputMode="decimal" disabled={disabled} value={text} onChange={e=>{setText(e.target.value);setError('');}} onBlur={()=>{try{if(text.trim())cents(text);onChange(text);setError('');}catch(e){setError(errorText(e));}}}/></Field>;
}

