export function InquiryFormScreen() {
  const {state,profile,save,busy}=useCRM();const navigate=useNavigate();const [params]=useSearchParams();const editId=params.get('edit'),existing=state.inquiries.find(q=>q.id===editId);
  const initial=useMemo<Inquiry>(()=>existing||({...base(),clientId:params.get('client'),contactName:state.clients.find(c=>c.id===params.get('client'))?.name||'',contact:'',summary:'',modality:'Por definir',need:'Por conocer',needSource:'Por precisar con el contacto',channel:'Por registrar',receivedAt:iso(),respondedAt:null,responseDue:null,ruleVersion:null,requestedDate:'',responsible:profile,status:'Por responder',waitingClient:false,nextAction:'Precisar solicitud',actionDate:'',reason:'',confirmedAt:null}),[params.get('client'),profile,editId,existing?.revision]);
  const {draft,setDraft,clear,reset}=useFormDraft(editId?'inquiry-edit-'+editId:'inquiry-new',initial);const [error,setError]=useState('');
  const patch=(p:Partial<Inquiry>)=>setDraft({...draft,...p});
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');try{if(!draft.contactName.trim()||!draft.summary.trim())throw new Error('Escribe una referencia del contacto y qué solicita.');await save('inquiries',draft);clear();navigate('/consultas/'+draft.id);}catch(e){setError(errorText(e));}};
  if(editId&&!existing)return <Empty title="Consulta no encontrada" action={<Link to="/pedidos?tab=consultas">Volver</Link>}/>;
  return <><PageHeader title={editId?'Precisar consulta':'Nueva consulta'} description="Guarda lo esencial; puedes precisar precio, fecha y contenido después."/><Card><form onSubmit={submit}><ErrorBox error={error}/><div className="form-grid"><Field label="Cliente conocido"><Select value={draft.clientId||''} onChange={e=>{const c=state.clients.find(x=>x.id===e.target.value);patch({clientId:c?.id||null,contactName:c?.name||draft.contactName,contact:c?.phone||c?.instagram||draft.contact});}}><option value="">Aún no está identificado / nuevo contacto</option>{state.clients.filter(c=>!c.archived&&!c.mergedInto).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</Select></Field><Field label="Nombre o referencia del contacto"><Input required value={draft.contactName} onChange={e=>patch({contactName:e.target.value})}/></Field><Field label="Qué solicita"><Select value={draft.modality} onChange={e=>patch({modality:e.target.value as Inquiry['modality']})}><option>Por definir</option><option>Productos</option><option>Catering</option></Select></Field><Field label="Canal de esta consulta"><Select value={draft.channel} onChange={e=>patch({channel:e.target.value})}>{channels.map(c=><option key={c}>{c}</option>)}</Select></Field><div className="span-2"><Field label="Resumen"><Textarea required placeholder="Por ejemplo: solicita una caja para regalo, cantidad aún por confirmar." value={draft.summary} onChange={e=>patch({summary:e.target.value})}/></Field></div><Field label="Fecha y hora en que llegó (Lima)"><Input type="datetime-local" required disabled={!!editId} value={localTime(draft.receivedAt)} onChange={e=>patch({receivedAt:instant(e.target.value)})}/></Field><Field label="Teléfono, usuario o referencia (opcional)"><Input value={draft.contact} onChange={e=>patch({contact:e.target.value})}/></Field><Field label="Quién responde"><Select value={draft.responsible} onChange={e=>patch({responsible:e.target.value as Person})}>{people.map(p=><option key={p}>{p}</option>)}</Select></Field><Field label="Fecha solicitada, si se conoce"><Input type="date" value={draft.requestedDate} onChange={e=>patch({requestedDate:e.target.value})}/></Field><Field label="Qué sigue"><Input value={draft.nextAction} onChange={e=>patch({nextAction:e.target.value})}/></Field><Field label="Cuándo retomar"><Input type="date" value={draft.actionDate} onChange={e=>patch({actionDate:e.target.value})}/></Field></div><details><summary>Necesidad de compra, si fue comunicada</summary><Field label="Necesidad"><Select value={draft.need} onChange={e=>patch({need:e.target.value as Need})}>{needs.map(n=><option key={n}>{n}</option>)}</Select></Field><Field label="Cómo se identificó"><Input value={draft.needSource} onChange={e=>patch({needSource:e.target.value})}/></Field></details><Actions><Button disabled={busy}>Guardar consulta</Button><Button type="button" variant="secondary" onClick={()=>navigate('/pedidos?tab=consultas')}>Volver; conservar borrador</Button><Button type="button" variant="ghost" onClick={reset}>Descartar este borrador</Button></Actions></form></Card></>;
}

export function InquiryDetailScreen() {
  const {id:inquiryId}=useParams();const {state,actor,save,busy,notify}=useCRM();const q=state.inquiries.find(x=>x.id===inquiryId);
  const [modal,setModal]=useState<'response'|'quote'|'follow'|'lost'|'duplicate'|null>(null),[text,setText]=useState(''),[when,setWhen]=useState(localTime(iso())),[actionDate,setActionDate]=useState(''),[waiting,setWaiting]=useState(false),[duplicate,setDuplicate]=useState(''),[interactionId,setInteractionId]=useState(id()),[error,setError]=useState('');
  if(!q)return <Empty title="Consulta no encontrada" action={<Link to="/pedidos?tab=consultas">Volver a consultas</Link>}/>;
  const orders=state.orders.filter(o=>o.inquiryId===q.id),interactions=state.interactions.filter(i=>i.inquiryId===q.id).sort((a,b)=>b.date.localeCompare(a.date));
  const link=whatsapp(contactPhone(state,q));
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');try{
    if(modal==='response'||modal==='quote'){if(!text.trim())throw new Error('Resume la respuesta o cotización que realmente enviaste.');const at=instant(when);if(at<q.receivedAt)throw new Error('La respuesta no puede preceder la consulta.');await save('inquiries',{...q,respondedAt:q.respondedAt&&q.respondedAt<at?q.respondedAt:at,status:modal==='quote'?(q.confirmedAt?'Con pedido':'Cotización enviada'):q.status==='Por responder'?'En conversación':q.status,waitingClient:waiting});if(!state.interactions.some(i=>i.id===interactionId))await save('interactions',{...base(),id:interactionId,clientId:q.clientId,inquiryId:q.id,orderId:null,date:at,channel:q.channel,summary:text,author:actor,kind:'Respuesta',outcome:modal==='quote'?'Cotización enviada':waiting?'Esperando al cliente':''});}
    if(modal==='follow'){if(!text.trim())throw new Error('Indica la siguiente acción.');await save('inquiries',{...q,nextAction:text,actionDate,waitingClient:waiting});}
    if(modal==='lost'){if(q.confirmedAt||orders.some(o=>o.confirmedAt))throw new Error('Hay un pedido confirmado o entregado. Revisa ese pedido antes de cerrar la consulta.');await save('inquiries',{...q,status:'No se concretó',reason:text||'No comunicado',nextAction:'',actionDate:''});}
    if(modal==='duplicate'){if(!duplicate)throw new Error('Elige la consulta original.');await save('inquiries',{...q,status:'Duplicada',duplicateOf:duplicate,reason:text||'Vinculada a la consulta original'});}
    setModal(null);notify('Consulta actualizada.');
  }catch(e){setError(errorText(e));}};
  return <><PageHeader title={personName(state,q.clientId,q.contactName)} description={q.summary} actions={<><Link className="btn btn-secondary" to="/pedidos?tab=consultas">Volver</Link><Link className="btn btn-secondary" to={`/consultas/nueva?edit=${q.id}`}>Precisar consulta</Link>{link&&<a className="btn btn-secondary" href={link} target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a>}</>}/><div className="split-grid"><Card title="Consulta y próxima acción"><Badge tone={tone(q.status)}>{q.status}</Badge><p>{q.modality} · {q.channel} · {q.responsible}</p><p><strong>Recibida:</strong> {localTime(q.receivedAt).replace('T',' ')} (Lima)</p><p><strong>Primera respuesta:</strong> {q.respondedAt?localTime(q.respondedAt).replace('T',' '):'Sin respuesta registrada'}</p><p><strong>Plazo acordado:</strong> {q.responseDue?localTime(q.responseDue).replace('T',' '):'Sin plazo configurado'}</p><p><strong>Necesidad:</strong> {q.need} · {q.needSource}</p><p><strong>Qué sigue:</strong> {q.nextAction||'Por precisar'} · {dateLabel(q.actionDate)}</p>{q.waitingClient&&<Notice>Esperando información del cliente; no implica compra perdida.</Notice>}<div className="inline-actions"><Button onClick={()=>{setModal('response');setInteractionId(id());setText('');setWhen(localTime(iso()));setWaiting(q.waitingClient);setError('');}}>Registrar respuesta</Button><Button variant="secondary" onClick={()=>{setModal('quote');setInteractionId(id());setText('');setWhen(localTime(iso()));setWaiting(true);setError('');}}>Cotización enviada</Button><Button variant="secondary" onClick={()=>{setModal('follow');setText(q.nextAction);setActionDate(q.actionDate);setWaiting(q.waitingClient);setError('');}}>Qué sigue</Button>{['No se concretó','Duplicada'].includes(q.status)?<Button variant="ghost" disabled={busy} onClick={()=>void save('inquiries',{...q,status:q.respondedAt?'En conversación':'Por responder',duplicateOf:undefined,reason:''}).catch(e=>setError(errorText(e)))}>Reabrir</Button>:<Button variant="ghost" onClick={()=>{setModal('lost');setText('');setError('');}}>No se concretó</Button>}<Button variant="ghost" onClick={()=>{setModal('duplicate');setDuplicate('');setText('');setError('');}}>Vincular duplicada</Button></div><ErrorBox error={!modal?error:''}/></Card><Card title="Pedidos de esta consulta" action={<Link className="text-link" to={`/pedidos/nuevo?inquiry=${q.id}&modality=${q.modality==='Catering'?'Catering':'Productos'}`}>Preparar pedido</Link>}>{orders.length?orders.map(o=><div className="list-row" key={o.id}><Link className="text-link" to={'/pedidos/'+o.id}>{o.code} · {money(o.total)}</Link><Badge tone={tone(o.status)}>{o.status}</Badge></div>):<Empty text="Preparar un borrador no confirma un pedido ni crea una venta."/>}{q.clientId?<Link className="text-link" to={'/clientes/'+q.clientId}>Ver historial del cliente</Link>:<Link className="text-link" to={`/clientes?new=1&inquiry=${q.id}`}>Identificar contacto cuando corresponda</Link>}</Card></div><Card title="Interacciones registradas">{interactions.length?interactions.map(i=><article className="list-row" key={i.id}><div><strong>{i.kind} · {dateLabel(i.date)}</strong><p>{i.summary}</p><small>{i.author} · {i.channel} {i.outcome}</small></div></article>):<Empty text="Abrir WhatsApp no registra una respuesta. Resume lo acordado cuando realmente atiendas."/>}</Card>
  <Modal open={!!modal} onClose={()=>setModal(null)} title={modal==='response'?'Registrar la respuesta enviada':modal==='quote'?'Registrar la cotización realmente enviada':modal==='follow'?'Programar siguiente acción':modal==='duplicate'?'Vincular consulta duplicada':'Cerrar sin compra'}><form onSubmit={submit}><ErrorBox error={error}/>{modal==='duplicate'&&<Field label="Consulta original"><Select required value={duplicate} onChange={e=>setDuplicate(e.target.value)}><option value="">Selecciona</option>{state.inquiries.filter(i=>i.id!==q.id&&i.status!=='Duplicada'&&!i.archived).map(i=><option key={i.id} value={i.id}>{i.contactName} · {i.summary}</option>)}</Select></Field>}<Field label={modal==='follow'?'Qué hacer':modal==='lost'?'Motivo comunicado, si se conoce':'Resumen'}><Textarea data-modal-first value={text} onChange={e=>setText(e.target.value)}/></Field>{(modal==='response'||modal==='quote')&&<Field label="Fecha y hora real de esta respuesta (Lima)"><Input required type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/></Field>}{modal==='follow'&&<Field label="Fecha para retomar"><Input type="date" value={actionDate} onChange={e=>setActionDate(e.target.value)}/></Field>}{(modal==='follow'||modal==='response'||modal==='quote')&&<label className="row"><input type="checkbox" checked={waiting} onChange={e=>setWaiting(e.target.checked)}/>Estamos esperando información del cliente</label>}<Actions><Button disabled={busy}>Guardar</Button><Button type="button" variant="secondary" onClick={()=>setModal(null)}>Cancelar</Button></Actions></form></Modal></>;
}

function ScopeEditor({scope,onChange}:{scope:ScopeItem[];onChange:(scope:ScopeItem[])=>void}) {
  const update=(index:number,p:Partial<ScopeItem>)=>onChange(scope.map((s,i)=>i===index?{...s,...p}:s));
  return <div className="stack"><Notice>El precio de alimentos está en las líneas. Solo «Adicional cotizado» se suma aquí; «Incluido» describe el alcance sin duplicar el importe.</Notice>{scope.map((s,i)=><div className="form-section" key={i}><div className="form-grid"><Field label="Componente"><Input value={s.name} onChange={e=>update(i,{name:e.target.value})}/></Field><Field label="Alcance"><Select value={s.status} onChange={e=>update(i,{status:e.target.value as ScopeItem['status'],amount:e.target.value==='Adicional cotizado'?s.amount:null})}>{['Incluido','Adicional cotizado','No incluido','Por confirmar','No aplica'].map(v=><option key={v}>{v}</option>)}</Select></Field><Field label="Tareas y recursos"><Textarea value={s.detail} onChange={e=>update(i,{detail:e.target.value})}/></Field><Field label="Quién lo aporta o realiza"><Input value={s.responsible} onChange={e=>update(i,{responsible:e.target.value})}/></Field>{s.status==='Adicional cotizado'&&<MoneyInput label="Adicional (S/)" value={s.amount} onChange={text=>update(i,{amount:text.trim()?cents(text):null})}/>}<Button type="button" variant="ghost" onClick={()=>onChange(scope.filter((_,j)=>j!==i))}>Quitar componente</Button></div></div>)}<Button type="button" variant="secondary" onClick={()=>onChange([...scope,{name:'',status:'Por confirmar',detail:'',amount:null,responsible:''}])}>Añadir componente</Button></div>;
}

export function OrderFormScreen() {
  const {state,profile}=useCRM();const [params]=useSearchParams();const editId=params.get('edit'),q=state.inquiries.find(i=>i.id===params.get('inquiry')),order=state.orders.find(o=>o.id===editId);
  const initial=useMemo(()=>{const o=order||blankOrder(profile,q),event=state.fairs.find(f=>f.id===params.get('event'));return order?o:{...o,eventId:event?.id||null,deliveryDate:event?.date||o.deliveryDate,location:event?.location||o.location,modality:params.get('modality')==='Catering'?'Catering':o.modality,scope:params.get('modality')==='Catering'||o.modality==='Catering'?['Montaje','Menaje','Atención','Transporte y retorno','Apoyo'].map(name=>({name,status:'Por confirmar' as const,detail:'',amount:null,responsible:''})):[]};},[editId,order?.revision,q?.id,q?.revision,profile,params.get('modality'),params.get('event')]);
  if(editId&&!order)return <Empty title="Pedido no encontrado" action={<Link to="/pedidos">Volver</Link>}/>;
  if(order&&['Entregado','Cancelado'].includes(order.status))return <Empty title="El acuerdo cerrado conserva su historia" text="Usa los ajustes o la corrección de costos desde el detalle; no reemplaces una venta ya realizada." action={<Link to={'/pedidos/'+order.id}>Ver pedido</Link>}/>;
  return <OrderEditor key={editId||q?.id||params.get('event')||'new'} initial={initial}/>;
}

function OrderEditor({initial}:{initial:Order}) {
  const {state,profile,save,busy}=useCRM();const navigate=useNavigate();const {draft,setDraft,clear,reset}=useFormDraft('order-'+(initial.revision?initial.id:initial.inquiryId?`inquiry-${initial.inquiryId}`:initial.eventId?`event-${initial.eventId}-${initial.modality}`:'new'),initial);const [step,setStep]=useState('cliente'),[error,setError]=useState('');
  const patch=(p:Partial<Order>)=>setDraft({...draft,...p});
  const total=orderTotal(draft),missing=draft.lines.some(l=>l.unitPrice===null)||draft.transport===null||draft.scope.some(s=>s.status==='Adicional cotizado'&&s.amount===null);
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');try{if(!draft.contactName.trim()&&!draft.clientId)throw new Error('Identifica a la persona o institución del pedido.');for(const l of draft.lines){if(!l.name.trim()||!l.unit.trim())throw new Error('Completa nombre y unidad de cada línea.');if(!Number.isInteger(l.quantity)||l.quantity<=0||!Number.isInteger(l.unitsPerPack)||l.unitsPerPack<=0||!Number.isInteger(l.baseQuantity)||l.baseQuantity<=0)throw new Error('Revisa cantidades enteras positivas y la base de cada precio.');if(l.unitPrice!==null&&l.unitPrice<0)throw new Error('Un precio no puede ser negativo.');}if(draft.discount<0||draft.extra<0||draft.transport!==null&&draft.transport<0)throw new Error('Adicionales, descuento y transporte deben ser importes no negativos.');if(total<0)throw new Error('El descuento no puede superar el importe del pedido.');await save('orders',{...draft,total});clear();navigate('/pedidos/'+draft.id);}catch(e){setError(errorText(e));}};
  return <><PageHeader title={initial.revision?'Revisar el pedido':'Preparar pedido'} description="Guarda un borrador mientras precisas las condiciones. La revisión y aceptación se registran después."/><Notice>Un cambio comercial de un pedido confirmado conserva la versión anterior y exige volver a revisar y confirmar.</Notice><Tabs value={step} onChange={setStep} values={[{id:'cliente',label:'1. Cliente'},{id:'contenido',label:'2. Contenido'},{id:'entrega',label:'3. Condiciones'},{id:'resumen',label:'4. Resumen'}]}/><form onSubmit={submit}><ErrorBox error={error}/>
  {step==='cliente'&&<Card title="Cliente y ocasión"><div className="form-grid"><Field label="Cliente registrado"><Select value={draft.clientId||''} onChange={e=>{const c=state.clients.find(c=>c.id===e.target.value);patch({clientId:c?.id||null,contactName:c?.name||draft.contactName});}}><option value="">Contacto aún no registrado</option>{state.clients.filter(c=>!c.archived&&!c.mergedInto).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</Select></Field><Field label="Nombre o institución"><Input value={draft.contactName} onChange={e=>patch({contactName:e.target.value})}/></Field><Field label="Modalidad"><Select value={draft.modality} onChange={e=>{const m=e.target.value as Order['modality'];patch({modality:m,deliveryMode:m==='Catering'?'Servicio':'Entrega',scope:m==='Catering'&&!draft.scope.length?['Montaje','Menaje','Atención','Transporte y retorno','Apoyo'].map(name=>({name,status:'Por confirmar',detail:'',amount:null,responsible:''})):draft.scope});}}><option>Productos</option><option>Catering</option></Select></Field><Field label="Necesidad de esta compra"><Select value={draft.need} onChange={e=>patch({need:e.target.value as Need})}>{needs.map(n=><option key={n}>{n}</option>)}</Select></Field><Field label="Responsable"><Select value={draft.responsible} onChange={e=>patch({responsible:e.target.value as Person})}>{people.map(p=><option key={p}>{p}</option>)}</Select></Field><label className="row"><input type="checkbox" checked={draft.isSimulation} onChange={e=>patch({isSimulation:e.target.checked})}/>Ejercicio de prueba, separado de operaciones reales</label>{draft.modality==='Catering'&&<><Field label="Asistentes, si se conoce"><Input type="number" min="1" step="1" value={draft.attendees??''} onChange={e=>patch({attendees:e.target.value?Number(e.target.value):null})}/></Field><Field label="Duración y horarios del servicio"><Input value={draft.duration} onChange={e=>patch({duration:e.target.value})}/></Field></>}</div><p className="muted">Una persona puede comprar para diferentes ocasiones. Los asistentes no determinan automáticamente las cantidades.</p></Card>}
  {step==='contenido'&&<><OrderLinesEditor state={state} lines={draft.lines} onChange={lines=>patch({lines})}/>{draft.modality==='Catering'&&<Card title="Servicios, incluidos y adicionales"><ScopeEditor scope={draft.scope} onChange={scope=>patch({scope})}/></Card>}</>}
  {step==='entrega'&&<Card title="Entrega y condiciones"><div className="form-grid"><Field label="Forma de entrega"><Select value={draft.deliveryMode} onChange={e=>patch({deliveryMode:e.target.value as Order['deliveryMode'],transport:e.target.value==='Retiro'?0:draft.transport})}><option>Retiro</option><option>Entrega</option>{draft.modality==='Catering'&&<option>Servicio</option>}</Select></Field><Field label="Fecha"><Input type="date" value={draft.deliveryDate} onChange={e=>patch({deliveryDate:e.target.value})}/></Field><Field label="Hora o franja"><Input value={draft.deliveryTime} placeholder="Por ejemplo: de 10 a 12" onChange={e=>patch({deliveryTime:e.target.value})}/></Field><Field label="Lugar"><Input value={draft.location} onChange={e=>patch({location:e.target.value})}/></Field><MoneyInput label="Transporte adicional (S/)" value={draft.transport} hint="0 solo si se acordó que no se cobra aparte; vacío significa por coordinar. No repitas el transporte cotizado en el alcance." onChange={text=>patch({transport:text.trim()?cents(text):null})}/><MoneyInput label="Otros adicionales (S/)" value={draft.extra} onChange={text=>patch({extra:text.trim()?cents(text):0})}/><MoneyInput label="Descuento acordado (S/)" value={draft.discount} onChange={text=>patch({discount:text.trim()?cents(text):0})}/><Field label="Fecha de cobro acordada, si existe"><Input type="date" value={draft.dueDate} onChange={e=>patch({dueDate:e.target.value})}/></Field><div className="span-2"><Field label="Condiciones de pago"><Textarea value={draft.paymentTerms} onChange={e=>patch({paymentTerms:e.target.value})} placeholder="Lo realmente acordado; no se exige un porcentaje de anticipo por defecto."/></Field></div><div className="span-2"><Field label="Personalización y cambios admitidos"><Textarea value={draft.changesTerms} onChange={e=>patch({changesTerms:e.target.value})}/></Field></div><div className="span-2"><Field label="Observaciones que se compartirán con el cliente"><Textarea value={draft.customerNotes} onChange={e=>patch({customerNotes:e.target.value})}/></Field></div><div className="span-2"><Field label="Notas internas, no incluidas en el acuerdo"><Textarea value={draft.internalNotes} onChange={e=>patch({internalNotes:e.target.value})}/></Field></div></div></Card>}
  {step==='resumen'&&<><OrderSummary state={state} order={{...draft,total}}/><Card title="Estimación interna del costo"><Notice>El costo es una estimación revisada, no un pago. No aparece en el documento que recibe el cliente.</Notice><MoneyInput label="Costo atribuible revisado (S/)" value={draft.costEstimate} onChange={text=>patch({costEstimate:text.trim()?cents(text):null,costReviewed:false})}/><label className="row"><input type="checkbox" checked={draft.costReviewed} onChange={e=>patch({costReviewed:e.target.checked,costRevision:draft.costRevision+1})}/>Revisé insumos, rendimiento, empaque, trabajo y adicionales de esta versión</label></Card></>}
  {missing&&<Notice tone="warning">Hay precios, transporte o adicionales por precisar. {money(total)} es únicamente el subtotal conocido; no un precio definitivo.</Notice>}<Actions><Button disabled={busy}>Guardar borrador / cambios</Button>{step!=='resumen'&&<Button type="button" variant="secondary" onClick={()=>setStep(['cliente','contenido','entrega','resumen'][['cliente','contenido','entrega','resumen'].indexOf(step)+1])}>Continuar</Button>}<Button type="button" variant="ghost" onClick={()=>navigate(initial.revision?'/pedidos/'+initial.id:'/pedidos')}>Volver; conservar borrador</Button><Button type="button" variant="ghost" onClick={reset}>Descartar cambios</Button></Actions></form><p className="muted">Registrando como {profile}. Guardar no confirma al cliente ni registra dinero.</p></>;
}

export function OrderSummary({state,order}:{state:AppState;order:Order}) {
  return <Card title={`${order.code} · ${personName(state,order.clientId,order.contactName)}`} subtitle={`${order.modality} · ${order.need}`}><div className="stack">{order.lines.map(l=><div key={l.id}><strong>{l.quantity} {l.unit} · {l.name}</strong><p>{l.attributes}</p><p>{money(l.unitPrice)} por {l.baseQuantity} {l.unit}{l.unitsPerPack>1&&` · ${l.quantity*l.unitsPerPack} productos contenidos`}</p>{l.distribution.length>0&&<small>{l.distribution.map(d=>`${d.quantity} ${d.variant}`).join(' · ')}</small>}{l.notes&&<p>{l.notes}</p>}</div>)}{order.scope.map((s,i)=><div className="row" key={i}><strong>{s.name}</strong><Badge tone={s.status==='Por confirmar'?'warning':'neutral'}>{s.status}</Badge><span>{s.detail}</span>{s.status==='Adicional cotizado'&&<span>{money(s.amount)}</span>}</div>)}<p><strong>Entrega/servicio:</strong> {dateLabel(order.deliveryDate)} · {order.deliveryTime||'Franja por precisar'} · {order.location||'Lugar por precisar'}</p><p>Transporte: {money(order.transport)} · Adicionales: {money(order.extra)} · Descuento: {money(order.discount)}</p><p><strong>Total del acuerdo:</strong> {money(order.total)}</p><p><strong>Pago:</strong> {order.paymentTerms||'Por acordar'}</p><p><strong>Cambios:</strong> {order.changesTerms||'Por acordar'}</p>{order.customerNotes&&<p>{order.customerNotes}</p>}</div></Card>;
}

type SplitMoney={transport:string;extra:string;discount:string;scope:Record<number,string>};
type SplitDistribution=Record<string,Record<number,number>>;

/** Allocate every concept explicitly and preserve the original commercial total. */
function splitParts(order:Order,counts:Record<string,number>,distribution:SplitDistribution,allocation:SplitMoney,date:string) {
  if(order.transport===null)throw new Error('Precisa primero el transporte del acuerdo original.');
  const first:OrderLine[]=[],second:OrderLine[]=[];
  for(const line of order.lines){
    const count=counts[line.id]??0;
    if(!Number.isInteger(count)||count<0||count>line.quantity)throw new Error('Las cantidades de cada entrega deben ser enteras y conservar el total.');
    const a:OrderLine={...line,quantity:count,distribution:[]},b:OrderLine={...line,quantity:line.quantity-count,distribution:[]};
    if(line.distribution.length){for(const [i,variant] of line.distribution.entries()){const n=distribution[line.id]?.[i]??0;if(!Number.isInteger(n)||n<0||n>variant.quantity)throw new Error(`Revisa el reparto de ${variant.variant} en ${line.name}.`);if(n)a.distribution.push({...variant,quantity:n});if(variant.quantity-n)b.distribution.push({...variant,quantity:variant.quantity-n});}if(a.distribution.reduce((n,v)=>n+v.quantity,0)!==a.quantity*a.unitsPerPack||b.distribution.reduce((n,v)=>n+v.quantity,0)!==b.quantity*b.unitsPerPack)throw new Error(`La distribución de ${line.name} debe coincidir con los productos de cada entrega.`);}
    if(count)first.push(a);if(line.quantity-count)second.push(b);
  }
  if(!first.length||!second.length)throw new Error('Cada entrega necesita al menos una línea de contenido.');
  const share=(text:string,total:number,label:string)=>{if(!text.trim())throw new Error(`Indica cuánto de ${label} corresponde a la primera entrega, incluso si es cero.`);const n=cents(text);if(n<0||n>total)throw new Error(`El reparto de ${label} debe estar entre cero y ${money(total)}.`);return n;};
  const ta=share(allocation.transport,order.transport,'transporte'),ea=share(allocation.extra,order.extra,'adicionales'),da=share(allocation.discount,order.discount,'descuento');
  const scopeA:ScopeItem[]=[],scopeB:ScopeItem[]=[];
  for(const [i,s] of order.scope.entries()){if(s.status==='Por confirmar')throw new Error(`Precisa el alcance de ${s.name} antes de dividir.`);if(s.status==='Adicional cotizado'){if(s.amount===null)throw new Error(`Precisa el importe de ${s.name}.`);const n=share(allocation.scope[i]??'',s.amount,s.name);scopeA.push({...s,amount:n});scopeB.push({...s,amount:s.amount-n});}else{scopeA.push({...s,amount:null});scopeB.push({...s,amount:null});}}
  const a={...order,lines:first,scope:scopeA,transport:ta,extra:ea,discount:da,deliveryDate:order.deliveryDate};
  const b={...order,lines:second,scope:scopeB,transport:order.transport-ta,extra:order.extra-ea,discount:order.discount-da,deliveryDate:date};
  const rounding=order.total-orderTotal(a)-orderTotal(b);
  // Keep the documented agreed total when proportional line rounding leaves cents.
  if(rounding>0)b.extra+=rounding;else if(rounding<0)b.discount-=rounding;
  const totalA=orderTotal(a),totalB=orderTotal(b);
  if(totalA<0||totalB<0)throw new Error('El descuento de cada entrega no puede superar sus conceptos; revisa el reparto.');
  return {a:{...a,total:totalA},b:{...b,total:totalB},rounding};
}

function SplitEditor({order,counts,onCounts,distribution,onDistribution,allocation,onAllocation,date,onDate}:{order:Order;counts:Record<string,number>;onCounts:(c:Record<string,number>)=>void;distribution:SplitDistribution;onDistribution:(d:SplitDistribution)=>void;allocation:SplitMoney;onAllocation:(a:SplitMoney)=>void;date:string;onDate:(d:string)=>void}) {
  let preview:ReturnType<typeof splitParts>|null=null,previewError='';try{preview=splitParts(order,counts,distribution,allocation,date);}catch(e){previewError=errorText(e);}
  return <div className="stack"><Notice>Reparte cantidades, rellenos y conceptos del precio. Los cobros existentes se reasignan una sola vez; las tareas y los recursos deberán revisarse para cada nueva fecha.</Notice>{order.lines.map(line=><Card key={line.id} title={line.name}><div className="row"><Field label={`Primera entrega, de ${line.quantity} ${line.unit}`}><Input type="number" min="0" max={line.quantity} step="1" value={counts[line.id]??0} onChange={e=>onCounts({...counts,[line.id]:Number(e.target.value)})}/></Field><p>Segunda entrega: {line.quantity-(counts[line.id]??0)} {line.unit}</p></div>{line.distribution.map((v,i)=><div className="row" key={i}><Field label={`Primera entrega: ${v.variant} (total ${v.quantity})`}><Input type="number" min="0" max={v.quantity} step="1" value={distribution[line.id]?.[i]??0} onChange={e=>onDistribution({...distribution,[line.id]:{...distribution[line.id],[i]:Number(e.target.value)}})}/></Field><span>Segunda: {v.quantity-(distribution[line.id]?.[i]??0)}</span></div>)}</Card>)}<Field label="Fecha de la segunda entrega"><Input type="date" required value={date} onChange={e=>onDate(e.target.value)}/></Field><Card title="Reparto del precio"><div className="form-grid">{(['transport','extra','discount'] as const).map(key=><Field key={key} label={`Primera entrega: ${{transport:'transporte',extra:'adicionales',discount:'descuento'}[key]} (S/)`} hint={`Total original: ${money(order[key])}; la segunda conserva el resto.`}><Input inputMode="decimal" value={allocation[key]} onChange={e=>onAllocation({...allocation,[key]:e.target.value})}/></Field>)}{order.scope.map((s,i)=>s.status==='Adicional cotizado'&&<Field key={i} label={`Primera entrega: ${s.name} (S/)`} hint={`Total ${money(s.amount)}; la segunda conserva el resto.`}><Input inputMode="decimal" value={allocation.scope[i]??''} onChange={e=>onAllocation({...allocation,scope:{...allocation.scope,[i]:e.target.value}})}/></Field>)}</div></Card>{preview?<Notice tone="success">Primera: {money(preview.a.total)}. Segunda: {money(preview.b.total)}. Total conservado: {money(order.total)}.{preview.rounding!==0&&` Se documentará un ajuste de redondeo de ${money(Math.abs(preview.rounding))} en la segunda entrega.`}</Notice>:<p className="muted">Para completar el reparto: {previewError}</p>}{order.modality==='Catering'&&<Notice tone="warning">Cada subpedido conservará el alcance como punto de partida; precisa tareas, recursos y horarios de cada fecha antes de confirmarlo.</Notice>}</div>;
}

export function OrderDetailScreen() {
  const {id:orderId}=useParams();const {state,profile,actor,run,save,busy,notify}=useCRM();const o=state.orders.find(x=>x.id===orderId);
  const [modal,setModal]=useState<'confirm'|'deliver'|'cancel'|'adjust'|'task'|'split'|'cost'|null>(null),[error,setError]=useState(''),[accepted,setAccepted]=useState(localTime(iso())),[acceptedChannel,setAcceptedChannel]=useState(''),[capacity,setCapacity]=useState(false),[when,setWhen]=useState(today()),[reason,setReason]=useState(''),[amount,setAmount]=useState('0.00'),[task,setTask]=useState<Task|null>(null),[splitCounts,setSplitCounts]=useState<Record<string,number>>({}),[splitDate,setSplitDate]=useState(addDays(today(),1)),[splitDistribution,setSplitDistribution]=useState<SplitDistribution>({}),[splitAllocation,setSplitAllocation]=useState<SplitMoney>({transport:'',extra:'',discount:'',scope:{}}),[reviewed,setReviewed]=useState(false);
  if(!o)return <Empty title="Pedido no encontrado" action={<Link to="/pedidos">Volver</Link>}/>;
  const tasks=state.tasks.filter(t=>t.orderId===o.id&&!t.archived).sort((a,b)=>a.date.localeCompare(b.date)),moneyRecords=state.money.filter(m=>m.allocations.some(a=>a.entityId===o.id)),sale=state.sales.find(s=>s.orderId===o.id),children=state.orders.filter(x=>x.parentId===o.id);
  const open=(kind:typeof modal)=>{setModal(kind);setError('');setReason('');setWhen(today());setAmount('0.00');setCapacity(false);setAcceptedChannel(o.acceptedChannel||'');setAccepted(localTime(iso()));if(kind==='cost'){setAmount(decimal(o.costEstimate));setReviewed(o.costReviewed);}if(kind==='task')setTask({...base(),title:'',date:o.deliveryDate||today(),time:'',minutes:null,responsible:profile,collaborator:'',orderId:o.id,clientId:o.clientId,eventId:o.eventId,kind:'Preparación',status:'Pendiente',resource:'',resourceStatus:'No aplica',purpose:'Atender solicitud/pedido',notes:'',result:''});if(kind==='split'){setSplitCounts(Object.fromEntries(o.lines.map(l=>[l.id,0])));setSplitDistribution({});setSplitAllocation({transport:o.transport===0?'0.00':'',extra:o.extra===0?'0.00':'',discount:o.discount===0?'0.00':'',scope:Object.fromEntries(o.scope.map((s,i)=>[i,s.amount===0?'0.00':'']))});setSplitDate(o.deliveryDate||addDays(today(),1));}};
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');try{
    if(modal==='confirm'){if(!acceptedChannel.trim())throw new Error('Indica el canal por el que el cliente aceptó.');await run({type:'confirmOrder',id:o.id,acceptedAt:instant(accepted),acceptedChannel,capacityChecked:capacity});}
    if(modal==='deliver')await run({type:'deliverOrder',id:o.id,date:when});
    if(modal==='cancel'){if(!reason.trim())throw new Error('Registra el motivo de cancelación y el acuerdo.');const charge=cents(amount);if(charge<0)throw new Error('El cargo acordado no puede ser negativo.');await run({type:'cancelOrder',id:o.id,reason,charge});}
    if(modal==='adjust'){if(!reason.trim())throw new Error('Explica el ajuste comercial.');const value=cents(amount);if(value===0)throw new Error('Escribe un ajuste distinto de cero.');await run({type:'adjustOrder',id:o.id,amount:value,date:when,reason});}
    if(modal==='cost'){const estimate=amount.trim()?cents(amount):null;if(estimate!==null&&estimate<0)throw new Error('El costo no puede ser negativo.');if(reviewed&&estimate===null)throw new Error('Completa el importe revisado.');if(!reason.trim())throw new Error('Indica la fuente o motivo de revisión del costo.');await save('orders',{...o,costEstimate:estimate,costReviewed:reviewed,costRevision:o.costRevision+1},reason);}
    if(modal==='task'&&task){if(!task.title.trim()||!task.date)throw new Error('Indica qué hacer y para cuándo.');await save('tasks',task);}
    if(modal==='split'){
      if(!reason.trim())throw new Error('Explica la división acordada.');if(!splitDate||!o.deliveryDate)throw new Error('Indica la fecha de cada entrega.');
      const {a,b,rounding}=splitParts(o,splitCounts,splitDistribution,splitAllocation,splitDate);
      const makePart=(part:Order,suffix:string):Order=>({...part,...base(),code:o.code+suffix,lines:part.lines.map(l=>({...l,id:id()})),parentId:o.id,status:'Por confirmar',versions:[],acceptedAt:null,acceptedChannel:'',capacityCheckedAt:null,capacityCheckedBy:null,confirmedAt:null,deliveredAt:null,cancelledAt:undefined,costEstimate:null,costReviewed:false,costRevision:0,cancelReason:'',cancelCharge:0,internalNotes:[part.internalNotes,`División de ${o.code}: ${reason}`,suffix==='-B'&&rounding?`Ajuste documentado de redondeo del total original: ${money(rounding)}`:''].filter(Boolean).join('\n')});
      await run({type:'splitOrder',id:o.id,parts:[makePart(a,'-A'),makePart(b,'-B')],reason});
    }
    setModal(null);notify('Operación guardada.');
  }catch(e){setError(errorText(e));}};
  const updateTask=async(t:Task,status:Task['status'])=>{try{await save('tasks',{...t,status});}catch(e){setError(errorText(e));}};
  const commitments=state.tasks.filter(t=>t.orderId!==o.id&&t.date===o.deliveryDate&&!['Completada','Cancelada'].includes(t.status));
  return <><PageHeader title={o.code} description={`${personName(state,o.clientId,o.contactName)} · ${o.modality}`} actions={<><Link className="btn btn-secondary" to="/pedidos">Volver</Link>{!['Entregado','Cancelado'].includes(o.status)&&<Link className="btn btn-secondary" to={`/pedidos/nuevo?edit=${o.id}`}>Editar acuerdo</Link>}<Button variant="secondary" onClick={()=>void exportOrderPdf(state,o).catch(e=>setError(errorText(e)))}>Descargar acuerdo PDF</Button><Button variant="ghost" onClick={()=>void copyOrderText(state,o).then(()=>notify('Resumen copiado; revísalo antes de enviarlo.')).catch(e=>setError(errorText(e)))}>Copiar resumen</Button></>}/><ErrorBox error={!modal?error:''}/><div className="toolbar"><Badge tone={tone(o.status)}>{o.status==='Entregado'&&o.modality==='Catering'?'Servicio realizado':o.status}</Badge>{o.isSimulation&&<Badge>Ejercicio, excluido de resultados reales</Badge>}<strong>{money(o.total)}</strong><span>{money(orderBalance(state,o))} {orderBalance(state,o)<0?'a favor':'pendiente'}</span></div>
  <div className="inline-actions">{['Borrador','Por confirmar'].includes(o.status)&&!children.length&&<Button onClick={()=>open('confirm')}>Revisar y confirmar</Button>}{o.status==='Confirmado'&&<Button variant="secondary" disabled={busy} onClick={()=>void run({type:'orderStatus',id:o.id,status:'En preparación'}).catch(e=>setError(errorText(e)))}>En preparación</Button>}{['Confirmado','En preparación'].includes(o.status)&&!children.length&&<Button onClick={()=>open('deliver')}>{o.modality==='Catering'?'Registrar servicio realizado':'Registrar entrega'}</Button>}{!o.isSimulation&&<Link className="btn btn-secondary" to={`/dinero?order=${o.id}&action=cobro`}>Registrar cobro</Link>}{!['Entregado','Cancelado'].includes(o.status)&&!children.length&&<Button variant="ghost" onClick={()=>open('cancel')}>Cancelar pedido</Button>}{o.status==='Entregado'&&<Button variant="ghost" onClick={()=>open('adjust')}>Ajuste comercial</Button>}{!['Entregado','Cancelado'].includes(o.status)&&!children.length&&<Button variant="ghost" onClick={()=>open('split')}>Separar entregas</Button>}</div><OrderSummary state={state} order={o}/>{o.status==='Cancelado'&&<Notice tone="warning">Cancelación: {o.cancelReason}. Cargo acordado: {money(o.cancelCharge)}. Las devoluciones reales se registran por separado; la cancelación conserva el historial.</Notice>}
  <div className="split-grid"><Card title="Preparación y tareas" action={<Button variant="secondary" onClick={()=>open('task')}>Añadir tarea</Button>}>{tasks.length?tasks.map(t=><div className="list-row" key={t.id}><div className="list-main"><strong>{t.title}</strong><p>{dateLabel(t.date)} {t.time} · {t.responsible} · {t.minutes===null?'Duración por estimar':`${t.minutes} min`}</p><small>{t.resource} · {t.resourceStatus}</small></div><Select aria-label={'Estado de '+t.title} disabled={busy} value={t.status} onChange={e=>void updateTask(t,e.target.value as Task['status'])}>{['Pendiente','En curso','Completada','Cancelada'].map(s=><option key={s}>{s}</option>)}</Select></div>):<Empty text="Programa compras, preparación, empaque y traslados; un día vacío no acredita capacidad libre."/>}</Card><Card title="Cobros e historial de dinero" action={<Link className="text-link" to={`/dinero?order=${o.id}`}>Ver en Dinero</Link>}>{moneyRecords.length?moneyRecords.map(m=><div className="list-row" key={m.id}><div><strong>{m.kind} · {money(m.amount)}</strong><p>{dateLabel(m.date)} · {m.method}</p>{m.reversedBy&&<Badge>Revertido, conservado en historial</Badge>}</div></div>):<Empty text="Todavía no hay cobros registrados. Confirmar o entregar un pedido no crea dinero recibido."/>}{sale&&<p><strong>Venta después de ajustes:</strong> {money(sale.amount+sale.adjustments.reduce((n,a)=>n+a.amount,0))} · {dateLabel(sale.date)}{sale.adjustments.map(a=><span key={a.id} className="muted"> · {money(a.amount)}: {a.reason} ({dateLabel(a.date)})</span>)}</p>}</Card></div>
  <Card title="Costo interno revisado" action={<Button variant="ghost" onClick={()=>open('cost')}>Revisar estimación</Button>}><p>{o.costReviewed?money(o.costEstimate):'Por revisar'} · revisión {o.costRevision}</p><p className="muted">Una estimación no es utilidad neta ni salida de caja. El acuerdo del cliente no muestra estos datos.</p>{o.internalNotes&&<p><strong>Notas internas:</strong> {o.internalNotes}</p>}</Card>
  {children.length>0&&<Card title="Entregas separadas">{children.map(p=><div className="list-row" key={p.id}><Link to={'/pedidos/'+p.id}>{p.code} · {dateLabel(p.deliveryDate)}</Link><span>{money(p.total)}</span><Badge>{p.status}</Badge></div>)}</Card>}
  <Card title="Versiones y aceptación"><p>{o.acceptedAt?`Aceptado ${dateLabel(o.acceptedAt)} por ${o.acceptedChannel}`:'Sin aceptación vigente registrada'}</p><p>{o.capacityCheckedAt?`Disponibilidad revisada por ${o.capacityCheckedBy} · ${dateLabel(o.capacityCheckedAt)}`:'Disponibilidad por revisar'}</p>{o.versions.map((v,i)=><details key={i}><summary>{dateLabel(v.at)} · {v.by} · {v.reason} · {money(v.total)}</summary><p>{v.lines.map(l=>`${l.quantity} ${l.unit}: ${l.name}`).join(' · ')}</p><p>Fecha {dateLabel(v.deliveryDate)} · {v.paymentTerms}</p><p>{v.acceptedAt?'Versión aceptada en su momento':'Borrador de revisión'}</p></details>)}{state.audit.filter(a=>a.entityId===o.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(a=><p className="muted" key={a.id}>{dateLabel(a.createdAt)} · {a.actor} · {a.action}: {a.reason}</p>)}</Card>
  <Modal open={!!modal} onClose={()=>setModal(null)} wide={modal==='confirm'||modal==='split'} title={modal==='confirm'?'Revisar antes de confirmar':modal==='deliver'?'Registrar entrega o servicio realizado':modal==='cancel'?'Cancelar sin borrar el historial':modal==='adjust'?'Registrar ajuste comercial':modal==='split'?'Separar en dos entregas':modal==='cost'?'Revisar costo estimado':'Programar tarea'}><form onSubmit={submit}><ErrorBox error={error}/>
  {modal==='confirm'&&<><Notice>Revisa contenido, unidades, precio, entrega, condiciones y aceptación real del cliente. Confirmar no implica haber cobrado.</Notice>{o.lines.some(l=>l.unitPrice===null)&&<Notice tone="warning">Hay un precio por cotizar.</Notice>}{o.transport===null&&<Notice tone="warning">El transporte sigue por coordinar.</Notice>}{o.scope.filter(s=>s.status==='Por confirmar').map((s,i)=><Notice tone="warning" key={i}>{s.name}: falta precisar su alcance.</Notice>)}{commitments.length>0&&<Card title="Otros compromisos en esta fecha">{commitments.map(t=><p key={t.id}>{t.title} · {t.time||'Hora por precisar'} · {t.responsible} · {t.resourceStatus}</p>)}</Card>}<Field label="Fecha y hora de aceptación (Lima)"><Input required type="datetime-local" value={accepted} onChange={e=>setAccepted(e.target.value)}/></Field><Field label="Canal y referencia de aceptación"><Input required placeholder="WhatsApp; el cliente confirmó el contenido y la fecha" value={acceptedChannel} onChange={e=>setAcceptedChannel(e.target.value)}/></Field><label className="row"><input type="checkbox" checked={capacity} onChange={e=>setCapacity(e.target.checked)}/>Revisé compras, preparación, empaque, apoyo y traslado necesarios. Puedo cumplir este compromiso.</label></>}
  {(modal==='deliver'||modal==='adjust')&&<Field label="Fecha real"><Input required type="date" value={when} onChange={e=>setWhen(e.target.value)}/></Field>}
  {modal==='deliver'&&<Notice>Se registrará una venta de gestión de {money(o.total)} una sola vez. No se añade ningún cobro. Si sólo se entregó parte, separa primero las entregas.</Notice>}
  {(modal==='cancel'||modal==='adjust'||modal==='split'||modal==='cost')&&<Field label="Motivo o fuente de la revisión"><Textarea required data-modal-first value={reason} onChange={e=>setReason(e.target.value)}/></Field>}
  {(modal==='cancel'||modal==='adjust'||modal==='cost')&&<Field label={modal==='cancel'?'Cargo de cancelación expresamente acordado (S/)':modal==='adjust'?'Ajuste (S/): negativo reduce la venta; positivo la aumenta':'Costo atribuible revisado (S/)'}><Input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></Field>}
  {modal==='cancel'&&<Notice>Un cargo sólo corresponde si fue acordado. Cancelar no devuelve el dinero automáticamente; registra la devolución real en Dinero cuando ocurra.</Notice>}
  {modal==='adjust'&&<Notice>Este ajuste cambia el importe comercial y el pendiente. No registra una devolución o un cobro. Esas operaciones se anotan por separado en Dinero.</Notice>}
  {modal==='cost'&&<label className="row"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/>Revisé el costo completo atribuible de esta versión</label>}
  {modal==='task'&&task&&<div className="form-grid"><div className="span-2"><Field label="Qué hacer"><Input required data-modal-first value={task.title} onChange={e=>setTask({...task,title:e.target.value})}/></Field></div><Field label="Fecha"><Input required type="date" value={task.date} onChange={e=>setTask({...task,date:e.target.value})}/></Field><Field label="Hora, si se conoce"><Input type="time" value={task.time} onChange={e=>setTask({...task,time:e.target.value})}/></Field><Field label="Etapa"><Select value={task.kind} onChange={e=>setTask({...task,kind:e.target.value as Task['kind']})}>{['Atención','Compra','Preparación','Empaque','Entrega','Montaje','Seguimiento','Otra'].map(k=><option key={k}>{k}</option>)}</Select></Field><Field label="Responsable"><Select value={task.responsible} onChange={e=>setTask({...task,responsible:e.target.value as Person})}>{people.map(p=><option key={p}>{p}</option>)}</Select></Field><Field label="Duración estimada (minutos)"><Input type="number" min="1" value={task.minutes??''} onChange={e=>setTask({...task,minutes:e.target.value?Number(e.target.value):null})}/></Field><Field label="Colaboradora o apoyo"><Input value={task.collaborator} onChange={e=>setTask({...task,collaborator:e.target.value})}/></Field><Field label="Recurso necesario"><Input value={task.resource} onChange={e=>setTask({...task,resource:e.target.value})}/></Field><Field label="Disponibilidad del recurso"><Select value={task.resourceStatus} onChange={e=>setTask({...task,resourceStatus:e.target.value as Task['resourceStatus']})}><option>No aplica</option><option>Por confirmar</option><option>Confirmado</option></Select></Field><div className="span-2"><Field label="Notas"><Textarea value={task.notes} onChange={e=>setTask({...task,notes:e.target.value})}/></Field></div></div>}
  {modal==='split'&&<SplitEditor order={o} counts={splitCounts} onCounts={setSplitCounts} distribution={splitDistribution} onDistribution={setSplitDistribution} allocation={splitAllocation} onAllocation={setSplitAllocation} date={splitDate} onDate={setSplitDate}/>}
  <Actions><Button disabled={busy||(modal==='confirm'&&!capacity)}>{modal==='confirm'?'Confirmar compromiso':modal==='deliver'?'Registrar realizado':'Guardar'}</Button><Button type="button" variant="secondary" onClick={()=>setModal(null)}>Volver</Button></Actions></form></Modal><p className="muted">Historial de cambios identificado como {actor}.</p></>;
}
